        computeDiscountCents: () => 0,
      };
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: () => 500,
      };

      const cart = new Cart({
        discountPolicy,
        shippingCalculator,
        region: "US",
      });
      cart.add(makeProduct({ id: "a", unitPriceCents: 1000 }), 1);

      const result = await cart.checkout({ asyncTaxProvider });
      // subtotal=1000, discount=0, discounted=1000
      // async tax: 10% of 1000 = 100
      // shipping: 500
      // total = 1000 + 100 + 500 = 1600
      expect(result.totals.taxCents).toBe(100);
      expect(result.totals.shippingCents).toBe(500);
      expect(result.totals.totalCents).toBe(1600);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
    });

    it("async tax with discount and shipping composition", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.08),
      };

      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(20),
        shippingCalculator: new FlatShippingCalculator(300),
        region: "US-CA",
      });
      cart.add(makeProduct({ id: "x", unitPriceCents: 5000 }), 2);
      // subtotal = 10000
      // discount = 20% of 10000 = 2000
      // discounted = 8000
      // async tax = 8% of 8000 = 640
      // shipping = 300
      // total = 8000 + 640 + 300 = 8940

      const result = await cart.checkout({ asyncTaxProvider });
      expect(result.totals.subtotalCents).toBe(10000);
      expect(result.totals.discountCents).toBe(2000);
      expect(result.totals.taxCents).toBe(640);
      expect(result.totals.shippingCents).toBe(300);
      expect(result.totals.totalCents).toBe(8940);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
    });

    it("propagates asyncTaxProvider rejection", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
      };
      const cart = new Cart();
      cart.add(makeProduct({ unitPriceCents: 1000 }), 1);

      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
        "tax service down",
      );
    });

    it("full pipeline: priceFetcher + inventoryChecker + asyncTax", async () => {
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn()
          .mockResolvedValueOnce(2000) // product a
          .mockResolvedValueOnce(800), // product b
      };
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 50,
        }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.05),
      };

      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });

      // Refreshed subtotal: 2000*2 + 800*1 = 4800
      // discount = 0, discounted = 4800
      // tax = 5% of 4800 = 240
      // shipping = 0 (FreeShippingCalculator default)
      // total = 4800 + 240 + 0 = 5040
      expect(result.totals.subtotalCents).toBe(4800);
      expect(result.totals.taxCents).toBe(240);
      expect(result.totals.totalCents).toBe(5040);
      expect(inventoryChecker.check).toHaveBeenCalledTimes(2);
    });

    it("checkout on empty cart returns zero totals", async () => {
      const emptyCart = new Cart();
      const result = await emptyCart.checkout();
      expect(result.totals.totalCents).toBe(0);
      expect(result.lines).toHaveLength(0);
    });

    it("uses default InventoryError message when no reason provided", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 0,
        }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.message).toContain("insufficient stock");
        expect(invErr.available).toBe(0);
      }
    });
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([0, 100, 10000, -50])(
    "returns 0 regardless of subtotal (%i)",
    (subtotal) => {
      expect(policy.computeDiscountCents(subtotal)).toBe(0);
    },
  );
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([-1, 101, NaN, Infinity, -Infinity])(
      "rejects out-of-range percent %s",
      (percent) => {
        expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
      },
    );

    it.each([0, 50, 100])("accepts valid percent %i", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("computes 10% of 1000 cents as 100", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(1000)).toBe(100);
    });

    it("rounds down to nearest cent", () => {
      const policy = new PercentageDiscountPolicy(33);
      // 33% of 100 = 33.0
      expect(policy.computeDiscountCents(100)).toBe(33);
      // 33% of 101 = 33.33 → floor → 33
      expect(policy.computeDiscountCents(101)).toBe(33);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("100% discount equals full subtotal", () => {
      const policy = new PercentageDiscountPolicy(100);
      expect(policy.computeDiscountCents(5000)).toBe(5000);
    });

    it("0% discount returns 0", () => {
      const policy = new PercentageDiscountPolicy(0);
      expect(policy.computeDiscountCents(5000)).toBe(0);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([-1, -100])("rejects negative amount %i", (amount) => {
      expect(() => new FixedAmountDiscountPolicy(amount)).toThrow(RangeError);
    });

    it("rejects non-integer amount", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts zero", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns the fixed amount when subtotal exceeds it", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(1000)).toBe(500);
    });

    it("caps at subtotal when fixed amount exceeds subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(300)).toBe(300);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("returns subtotal when amount equals subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(1000);
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all child policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 1000 = 100, fixed 200 → sum = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("clamps negative child results to 0 before summing", () => {
      const negativePolicy = {
        computeDiscountCents: () => -100,
      };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // max(0, -100) + 200 = 200
      expect(composite.computeDiscountCents(1000)).toBe(200);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-500)).toBe(0);
    });

    it("can exceed subtotal (caller clamps)", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(600), new FixedAmountDiscountPolicy(600)],
        "sum",
      );
      // Each returns min(600, 1000)=600, sum=1200 > 1000
      expect(composite.computeDiscountCents(1000)).toBe(1200);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // First: 10% of 1000 = 100, remaining 900
      // Second: 10% of 900 = 90, remaining 810
      // Total discount = 190
      expect(composite.computeDiscountCents(1000)).toBe(190);
    });

    it("second policy sees reduced subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500), new PercentageDiscountPolicy(50)],
        "chain",
      );
      // Fixed 500 off 1000 → remaining 500
      // 50% of 500 = 250
      // Total = 750
      expect(composite.computeDiscountCents(1000)).toBe(750);
    });

    it("ordering matters in chain mode", () => {
      const policyA = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new FixedAmountDiscountPolicy(100)],
        "chain",
      );
      const policyB = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100), new PercentageDiscountPolicy(50)],
        "chain",
      );
      // A: 50% of 1000=500, remaining 500, fixed min(100,500)=100 → total=600
      // B: fixed 100 off 1000, remaining 900, 50% of 900=450 → total=550
      expect(policyA.computeDiscountCents(1000)).toBe(600);
      expect(policyB.computeDiscountCents(1000)).toBe(550);
    });

    it("stops compounding when remaining hits 0", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(1000),
          new PercentageDiscountPolicy(50),
        ],
        "chain",
      );
      // Fixed 1000 off 1000 → remaining 0
      // 50% of 0 = 0
      // Total discount = 1000
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("clamps negative child results to 0", () => {
      const negativePolicy = {
        computeDiscountCents: () => -50,
      };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(200)],
        "chain",
      );
      // max(0, -50) = 0 step, remaining still 1000
      // then fixed 200 → total = 200
      expect(composite.computeDiscountCents(1000)).toBe(200);
    });
  });

  it("defaults to sum mode when not specified", () => {
    const composite = new CompositeDiscountPolicy([
      new FixedAmountDiscountPolicy(100),
      new FixedAmountDiscountPolicy(200),
    ]);
    // sum: 100 + 200 = 300
    expect(composite.computeDiscountCents(1000)).toBe(300);
  });
});

import { describe, it, expect } from "vitest";
import {
  NoTaxCalculator,
  RegionalTaxCalculator,
  AsyncTaxCalculator,
  totalLineWeightGrams,
  type AsyncTaxRateProvider,
} from "../src/tax.ts";
import type { CartLine, Product } from "../src/product.ts";

function makeProduct(overrides: Partial<Product> = {}): Product {
  return { id: "p1", name: "Widget", unitPriceCents: 1000, ...overrides };
}

function makeLine(
  product: Partial<Product> = {},
  quantity = 1,
): CartLine {
  return { product: makeProduct(product), quantity };
}

describe("NoTaxCalculator", () => {
  const calc = new NoTaxCalculator();

  it.each([
    [0, "US"],
    [1000, "FR"],
    [-500, "GB"],
  ])("returns 0 for taxable=%i region=%s", (taxable, region) => {
    expect(calc.computeTaxCents(taxable, region)).toBe(0);
  });
});

describe("RegionalTaxCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative defaultRate", () => {
      expect(() => new RegionalTaxCalculator({}, -0.01)).toThrow(RangeError);
    });

    it("rejects defaultRate > 1", () => {
      expect(() => new RegionalTaxCalculator({}, 1.01)).toThrow(RangeError);
    });

    it("rejects NaN defaultRate", () => {
      expect(() => new RegionalTaxCalculator({}, NaN)).toThrow(RangeError);
    });

    it("rejects invalid region rate", () => {
      expect(
        () => new RegionalTaxCalculator({ "US": 1.5 }),
      ).toThrow(RangeError);
    });

    it("rejects negative region rate", () => {
      expect(
        () => new RegionalTaxCalculator({ "US": -0.1 }),
      ).toThrow(RangeError);
    });

    it("accepts valid rates at boundaries", () => {
      expect(
        () => new RegionalTaxCalculator({ "US": 0, "FR": 1 }, 0),
      ).not.toThrow();
    });
  });

  describe("computeTaxCents", () => {
    const calc = new RegionalTaxCalculator(
      { "US": 0.0875, "US-CA": 0.0725, "FR": 0.20 },
      0.05,
    );

    it("uses region-specific rate", () => {
      // 8.75% of 1000 = 87.5 → floor → 87
      expect(calc.computeTaxCents(1000, "US")).toBe(87);
    });

    it("uses sub-region rate", () => {
      // 7.25% of 1000 = 72.5 → floor → 72
      expect(calc.computeTaxCents(1000, "US-CA")).toBe(72);
    });

    it("falls back to default rate for unknown region", () => {
      // 5% of 1000 = 50
      expect(calc.computeTaxCents(1000, "JP")).toBe(50);
    });

    it("rounds down to nearest cent", () => {
      // 20% of 333 = 66.6 → floor → 66
      expect(calc.computeTaxCents(333, "FR")).toBe(66);
    });

    it("returns 0 for zero taxable", () => {
      expect(calc.computeTaxCents(0, "US")).toBe(0);
    });

    it("returns 0 for negative taxable", () => {
      expect(calc.computeTaxCents(-100, "US")).toBe(0);
    });

    it("defaults defaultRate to 0 when omitted", () => {
      const calcNoDefault = new RegionalTaxCalculator({ "US": 0.10 });
      expect(calcNoDefault.computeTaxCents(1000, "UNKNOWN")).toBe(0);
    });
  });
});

describe("AsyncTaxCalculator", () => {
  it("computes tax using provider rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => 0.10,
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(1000, "US")).toBe(100);
  });

  it("rounds down", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => 0.0875,
    };
    const calc = new AsyncTaxCalculator(provider);
    // 8.75% of 999 = 87.4125 → floor → 87
    expect(await calc.computeTaxCents(999, "US")).toBe(87);
  });

  it("returns 0 for zero taxable", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => 0.10,
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(0, "US")).toBe(0);
  });

  it("returns 0 for negative taxable", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => 0.10,
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(-100, "US")).toBe(0);
  });

  it("throws RangeError for rate > 1", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => 1.5,
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("throws RangeError for negative rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => -0.1,
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("throws RangeError for NaN rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => NaN,
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("propagates provider rejection", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => {
        throw new Error("service unavailable");
      },
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(
      "service unavailable",
    );
  });
});

