describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(9.99)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 99.5)).toThrow(RangeError);
    });

    it("accepts zero values", () => {
      expect(() => new FlatShippingCalculator(0, 0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns flat fee for non-empty cart", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([makeLine()], 1000)).toBe(599);
    });

    it("returns 0 for empty cart", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns 0 when subtotal meets free-over threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([makeLine()], 5000)).toBe(0);
    });

    it("returns 0 when subtotal exceeds free-over threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([makeLine()], 6000)).toBe(0);
    });

    it("returns flat fee when subtotal is below free-over threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([makeLine()], 4999)).toBe(599);
    });

    it("returns flat fee when no threshold is set", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([makeLine()], 100000)).toBe(599);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with non-positive upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 0, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1000, costCents: -1 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1.5, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1000, costCents: 99.9 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 100 }],
            99.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const brackets = [
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 2000, costCents: 600 },
      { upToGrams: 5000, costCents: 1200 },
    ];

    it("returns 0 for empty cart", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns 0 when total weight is 0", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // Product with no weight
      const lines = [makeLine({}, 2)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(0);
    });

    it("selects first bracket when weight is within it", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine({ weightGrams: 250 }, 1)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
    });

    it("selects bracket at exact boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine({ weightGrams: 500 }, 1)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
    });

    it("selects next bracket when weight exceeds boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine({ weightGrams: 501 }, 1)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(600);
    });

    it("selects middle bracket", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine({ weightGrams: 1000 }, 1)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(600);
    });

    it("selects highest bracket at its boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine({ weightGrams: 5000 }, 1)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(1200);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      const calc = new WeightBasedShippingCalculator(brackets, 2000);
      const lines = [makeLine({ weightGrams: 6000 }, 1)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(2000);
    });

    it("falls back to heaviest bracket cost when no overflow specified", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine({ weightGrams: 10000 }, 1)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(1200);
    });

    it("sums weight across multiple lines", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 200g * 2 + 300g * 1 = 700g → second bracket (500 < 700 <= 2000)
      const lines = [
        makeLine({ id: "a", weightGrams: 200 }, 2),
        makeLine({ id: "b", weightGrams: 300 }, 1),
      ];
      expect(calc.computeShippingCents(lines, 1000)).toBe(600);
    });

    it("sorts unsorted brackets correctly", () => {
      const unsorted = [
        { upToGrams: 5000, costCents: 1200 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 600 },
      ];
      const calc = new WeightBasedShippingCalculator(unsorted);
      const lines = [makeLine({ weightGrams: 250 }, 1)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import {
  InventoryError,
  refreshPrices,
  type PriceFetcher,
} from "../src/inventory.ts";
import type { CartLine, Product } from "../src/product.ts";

function makeProduct(overrides: Partial<Product> = {}): Product {
  return { id: "p1", name: "Widget", unitPriceCents: 1000, ...overrides };
}

function makeLine(
  product: Partial<Product> = {},
  quantity = 1,
): CartLine {
  return { product: makeProduct(product), quantity };
}

describe("InventoryError", () => {
  it("has correct shape and properties", () => {
    const err = new InventoryError("out of stock", "prod-1", 5, 2);
    expect(err).toBeInstanceOf(Error);
    expect(err).toBeInstanceOf(InventoryError);
    expect(err.name).toBe("InventoryError");
    expect(err.message).toBe("out of stock");
    expect(err.productId).toBe("prod-1");
    expect(err.requested).toBe(5);
    expect(err.available).toBe(2);
  });

  it("supports undefined available", () => {
    const err = new InventoryError("gone", "prod-2", 3, undefined);
    expect(err.available).toBeUndefined();
  });
});

describe("refreshPrices", () => {
  it("updates prices from fetcher", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn()
        .mockResolvedValueOnce(1500)
        .mockResolvedValueOnce(2500),
    };
    const lines: CartLine[] = [
      makeLine({ id: "a", unitPriceCents: 1000 }),
      makeLine({ id: "b", unitPriceCents: 2000 }),
    ];

    const refreshed = await refreshPrices(lines, fetcher);

    expect(refreshed).toHaveLength(2);
    expect(refreshed[0]!.product.unitPriceCents).toBe(1500);
    expect(refreshed[1]!.product.unitPriceCents).toBe(2500);
    expect(refreshed[0]!.product.id).toBe("a");
    expect(refreshed[1]!.product.id).toBe("b");
  });

  it("preserves quantity and other product fields", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(999),
    };
    const lines: CartLine[] = [
      makeLine({ id: "x", name: "Gadget", weightGrams: 500 }, 3),
    ];

    const refreshed = await refreshPrices(lines, fetcher);

    expect(refreshed[0]!.quantity).toBe(3);
    expect(refreshed[0]!.product.name).toBe("Gadget");
    expect(refreshed[0]!.product.weightGrams).toBe(500);
  });

  it("throws RangeError for negative fetched price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(-1),
    };

    await expect(
      refreshPrices([makeLine({ id: "bad" })], fetcher),
    ).rejects.toThrow(RangeError);
  });

  it("throws RangeError for non-integer fetched price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(10.5),
    };

    await expect(
      refreshPrices([makeLine({ id: "bad" })], fetcher),
    ).rejects.toThrow(RangeError);
  });

  it("propagates fetcher rejection", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("network error")),
    };

    await expect(
      refreshPrices([makeLine()], fetcher),
    ).rejects.toThrow("network error");
  });

  it("returns empty array for empty lines", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn(),
    };

    const refreshed = await refreshPrices([], fetcher);
    expect(refreshed).toEqual([]);
    expect(fetcher.fetchPriceCents).not.toHaveBeenCalled();
  });
});

import { describe, it, expect, vi, beforeEach } from "vitest";
import { Cart, type CartConfig } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import { InventoryError } from "../src/inventory.ts";
import {
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
} from "../src/pricing.ts";
import { RegionalTaxCalculator } from "../src/tax.ts";
import { FlatShippingCalculator } from "../src/shipping.ts";

function makeProduct(overrides: Partial<Product> = {}): Product {
  return { id: "p1", name: "Widget", unitPriceCents: 1000, ...overrides };
}

describe("Cart", () => {
  describe("add", () => {
    it("adds a product with given quantity", () => {
      const cart = new Cart();
      cart.add(makeProduct(), 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantity when adding the same product twice", () => {
      const cart = new Cart();
      const product = makeProduct();
      cart.add(product, 2);
      cart.add(product, 3);
      expect(cart.itemCount).toBe(5);
    });

    it("throws for zero quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(makeProduct(), 0)).toThrow(RangeError);
    });

    it("throws for negative quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(makeProduct(), -1)).toThrow(RangeError);
    });

    it("throws for non-integer quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(makeProduct(), 1.5)).toThrow(RangeError);
    });

    it("throws for negative unitPriceCents", () => {
      const cart = new Cart();
      expect(() =>
        cart.add(makeProduct({ unitPriceCents: -1 }), 1),
      ).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("removes an existing product and returns true", () => {
      const cart = new Cart();
      cart.add(makeProduct({ id: "x" }), 1);
      expect(cart.remove("x")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product id", () => {
      const cart = new Cart();
      expect(cart.remove("nonexistent")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity of existing product", () => {
      const cart = new Cart();
      cart.add(makeProduct({ id: "x" }), 3);
      cart.updateQuantity("x", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity set to 0", () => {
      const cart = new Cart();
      cart.add(makeProduct({ id: "x" }), 3);
      cart.updateQuantity("x", 0);
      expect(cart.itemCount).toBe(0);
      expect(cart.remove("x")).toBe(false);
    });

    it("throws for negative quantity", () => {
      const cart = new Cart();
      cart.add(makeProduct({ id: "x" }), 1);
      expect(() => cart.updateQuantity("x", -1)).toThrow(RangeError);
    });

    it("throws for non-integer quantity", () => {
      const cart = new Cart();
      cart.add(makeProduct({ id: "x" }), 1);
      expect(() => cart.updateQuantity("x", 2.5)).toThrow(RangeError);
    });

    it("throws for unknown product id", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("nonexistent", 1)).toThrow(
        "Product nonexistent is not in the cart",
      );
    });
  });

  describe("clear", () => {
    it("removes all items", () => {
      const cart = new Cart();
      cart.add(makeProduct({ id: "a" }), 2);
      cart.add(makeProduct({ id: "b" }), 3);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("itemCount", () => {
    it("returns 0 for empty cart", () => {
      expect(new Cart().itemCount).toBe(0);
    });

    it("sums quantities across products", () => {
      const cart = new Cart();
      cart.add(makeProduct({ id: "a" }), 2);
      cart.add(makeProduct({ id: "b" }), 3);
      expect(cart.itemCount).toBe(5);
    });
  });

  describe("snapshot", () => {
    it("returns a deep copy that does not affect cart state", () => {
      const cart = new Cart();
      cart.add(makeProduct({ id: "a", unitPriceCents: 500 }), 2);
      const snap = cart.snapshot();
      snap[0]!.quantity = 99;
      snap[0]!.product.unitPriceCents = 0;
      expect(cart.itemCount).toBe(2);
      expect(cart.totals().subtotalCents).toBe(1000);
    });
  });

  describe("totals (pricing pipeline)", () => {
    it("computes correct subtotal from multiple lines", () => {
      const cart = new Cart();
      cart.add(makeProduct({ id: "a", unitPriceCents: 1000 }), 2);
      cart.add(makeProduct({ id: "b", unitPriceCents: 500 }), 3);
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(3500); // 2000 + 1500
    });

    it("returns all-zero totals for empty cart", () => {
      const cart = new Cart();
      const totals = cart.totals();
      expect(totals).toEqual({
        subtotalCents: 0,
        discountCents: 0,
        taxCents: 0,
        shippingCents: 0,
        totalCents: 0,
      });
    });

    it("applies discount policy with clamping", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(300),
      };
      const cart = new Cart({ discountPolicy });
      cart.add(makeProduct({ unitPriceCents: 1000 }), 1);
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(1000);
      expect(totals.discountCents).toBe(300);
      expect(totals.totalCents).toBe(700);
    });

    it("clamps discount to subtotal (prevents negative)", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(5000),
      };
      const cart = new Cart({ discountPolicy });
      cart.add(makeProduct({ unitPriceCents: 1000 }), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(1000);
      expect(totals.totalCents).toBe(0);
    });

    it("clamps negative discount to 0", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ discountPolicy });
      cart.add(makeProduct({ unitPriceCents: 1000 }), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(0);
    });

    it("computes tax on discounted subtotal", () => {
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(50),
      };
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const cart = new Cart({ discountPolicy, taxCalculator });
      cart.add(makeProduct({ unitPriceCents: 1000 }), 1);
      const totals = cart.totals();
      // Tax called on discounted subtotal (1000-200=800)
      expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(800, "US");
      expect(totals.taxCents).toBe(50);
    });

    it("passes discounted subtotal to shipping calculator", () => {
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(500),
      };
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const cart = new Cart({ discountPolicy, shippingCalculator });
      cart.add(makeProduct({ unitPriceCents: 1000 }), 1);
      const totals = cart.totals();
      expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        800,
      );
      expect(totals.shippingCents).toBe(500);
    });

