import { describe, it, expect, vi, beforeEach } from "vitest";
import { Cart, type CartConfig } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import { InventoryError } from "../src/inventory.ts";
import {
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
} from "../src/pricing.ts";
import { RegionalTaxCalculator } from "../src/tax.ts";
import { FlatShippingCalculator } from "../src/shipping.ts";

function makeProduct(overrides: Partial<Product> = {}): Product {
  return { id: "p1", name: "Widget", unitPriceCents: 1000, ...overrides };
}

describe("Cart", () => {
  describe("add", () => {
    it("adds a product with given quantity", () => {
      const cart = new Cart();
      cart.add(makeProduct(), 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantity when adding the same product twice", () => {
      const cart = new Cart();
      const product = makeProduct();
      cart.add(product, 2);
      cart.add(product, 3);
      expect(cart.itemCount).toBe(5);
    });

    it("throws for zero quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(makeProduct(), 0)).toThrow(RangeError);
    });

    it("throws for negative quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(makeProduct(), -1)).toThrow(RangeError);
    });

    it("throws for non-integer quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(makeProduct(), 1.5)).toThrow(RangeError);
    });

    it("throws for negative unitPriceCents", () => {
      const cart = new Cart();
      expect(() =>
        cart.add(makeProduct({ unitPriceCents: -1 }), 1),
      ).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("removes an existing product and returns true", () => {
      const cart = new Cart();
      cart.add(makeProduct({ id: "x" }), 1);
      expect(cart.remove("x")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product id", () => {
      const cart = new Cart();
      expect(cart.remove("nonexistent")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity of existing product", () => {
      const cart = new Cart();
      cart.add(makeProduct({ id: "x" }), 3);
      cart.updateQuantity("x", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity set to 0", () => {
      const cart = new Cart();
      cart.add(makeProduct({ id: "x" }), 3);
      cart.updateQuantity("x", 0);
      expect(cart.itemCount).toBe(0);
      expect(cart.remove("x")).toBe(false);
    });

    it("throws for negative quantity", () => {
      const cart = new Cart();
      cart.add(makeProduct({ id: "x" }), 1);
      expect(() => cart.updateQuantity("x", -1)).toThrow(RangeError);
    });

    it("throws for non-integer quantity", () => {
      const cart = new Cart();
      cart.add(makeProduct({ id: "x" }), 1);
      expect(() => cart.updateQuantity("x", 2.5)).toThrow(RangeError);
    });

    it("throws for unknown product id", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("nonexistent", 1)).toThrow(
        "Product nonexistent is not in the cart",
      );
    });
  });

  describe("clear", () => {
    it("removes all items", () => {
      const cart = new Cart();
      cart.add(makeProduct({ id: "a" }), 2);
      cart.add(makeProduct({ id: "b" }), 3);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("itemCount", () => {
    it("returns 0 for empty cart", () => {
      expect(new Cart().itemCount).toBe(0);
    });

    it("sums quantities across products", () => {
      const cart = new Cart();
      cart.add(makeProduct({ id: "a" }), 2);
      cart.add(makeProduct({ id: "b" }), 3);
      expect(cart.itemCount).toBe(5);
    });
  });

  describe("snapshot", () => {
    it("returns a deep copy that does not affect cart state", () => {
      const cart = new Cart();
      cart.add(makeProduct({ id: "a", unitPriceCents: 500 }), 2);
      const snap = cart.snapshot();
      snap[0]!.quantity = 99;
      snap[0]!.product.unitPriceCents = 0;
      expect(cart.itemCount).toBe(2);
      expect(cart.totals().subtotalCents).toBe(1000);
    });
  });

  describe("totals (pricing pipeline)", () => {
    it("computes correct subtotal from multiple lines", () => {
      const cart = new Cart();
      cart.add(makeProduct({ id: "a", unitPriceCents: 1000 }), 2);
      cart.add(makeProduct({ id: "b", unitPriceCents: 500 }), 3);
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(3500); // 2000 + 1500
    });

    it("returns all-zero totals for empty cart", () => {
      const cart = new Cart();
      const totals = cart.totals();
      expect(totals).toEqual({
        subtotalCents: 0,
        discountCents: 0,
        taxCents: 0,
        shippingCents: 0,
        totalCents: 0,
      });
    });

    it("applies discount policy with clamping", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(300),
      };
      const cart = new Cart({ discountPolicy });
      cart.add(makeProduct({ unitPriceCents: 1000 }), 1);
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(1000);
      expect(totals.discountCents).toBe(300);
      expect(totals.totalCents).toBe(700);
    });

    it("clamps discount to subtotal (prevents negative)", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(5000),
      };
      const cart = new Cart({ discountPolicy });
      cart.add(makeProduct({ unitPriceCents: 1000 }), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(1000);
      expect(totals.totalCents).toBe(0);
    });

    it("clamps negative discount to 0", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ discountPolicy });
      cart.add(makeProduct({ unitPriceCents: 1000 }), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(0);
    });

    it("computes tax on discounted subtotal", () => {
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(50),
      };
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const cart = new Cart({ discountPolicy, taxCalculator });
      cart.add(makeProduct({ unitPriceCents: 1000 }), 1);
      const totals = cart.totals();
      // Tax called on discounted subtotal (1000-200=800)
      expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(800, "US");
      expect(totals.taxCents).toBe(50);
    });

    it("passes discounted subtotal to shipping calculator", () => {
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(500),
      };
